// Merge learning context with webhook input
const webhookData = $('Webhook Trigger').first().json;
const recentContent = $('Get Recent Content').all().map(item => item.json);
const voiceEvolution = $('Get Voice Evolution').all().map(item => item.json);

// Extract recent topics to avoid
const recentTopics = [...new Set(recentContent.map(c => c.week_topic).filter(Boolean))];

// Extract recent content snippets for context
const recentSnippets = recentContent.slice(0, 20).map(c => ({
  text: c.content_text?.substring(0, 100) + '...',
  category: c.category,
  platform: c.platform
}));

// Get latest voice insights
const latestVoice = voiceEvolution[0] || {};

return [{
  json: {
    ...webhookData,
    learning_context: {
      recent_topics: recentTopics,
      recent_snippets: recentSnippets,
      content_count_30_days: recentContent.length,
      voice_evolution: {
        latest_score: latestVoice.voice_score,
        notable_shifts: latestVoice.notable_shifts,
        tone_markers: latestVoice.tone_markers,
        vocabulary_patterns: latestVoice.vocabulary_patterns
      },
      avoid_similar_to: recentContent.slice(0, 10).map(c => c.content_text?.substring(0, 150))
    }
  }
}];

// Parse the topic selection response
const input = $input.first().json;
let response = input.text || input.content || input;

// Try to extract JSON from the response
let parsed;
try {
  // Handle if response is already an object
  if (typeof response === 'object') {
    parsed = response;
  } else {
    // Try to find JSON in the text
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = { selected_topic: response, format: 'Methodology Deep Dive' };
    }
  }
} catch (e) {
  parsed = { selected_topic: response, format: 'Methodology Deep Dive', error: e.message };
}

return [{
  json: {
    ...parsed,
    original_input: $('Webhook Trigger').first().json,
    timestamp: new Date().toISOString()
  }
}];

// Parse research response and merge with previous data
