const input = $input.first().json;
const prevData = $('Store Field Guide').first().json;

let response = input.text || input.content || input;
let parsed;

try {
  if (typeof response === 'object') {
    parsed = response;
  } else {
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = { raw_parsed: response };
    }
  }
} catch (e) {
  parsed = { raw_parsed: response, parse_error: e.message };
}

return [{
  json: {
    ...prevData,
    parsed_content: parsed
  }
}];

// Combine all generated content
const items = $input.all();
const baseData = $('Parse Extracted Content').first().json;

// Helper to parse JSON from response
function parseResponse(item) {
  const text = item.json?.text || item.json?.content || item.json;
  if (typeof text === 'object') return text;
  try {
    const match = text.match(/\[\s*\{[\s\S]*\}\s*\]|\{[\s\S]*\}/);
    if (match) return JSON.parse(match[0]);
  } catch (e) {}
  return { raw: text };
}

// Parse each content type
let tweets = [], threads = [], linkedin = [], analysis = {};

for (const item of items) {
  const parsed = parseResponse(item);
  const nodeName = item.json?.$node || '';

  if (Array.isArray(parsed)) {
    if (parsed[0]?.text && parsed[0]?.category) tweets = parsed;
    else if (parsed[0]?.hook_text) threads = parsed;
    else if (parsed[0]?.post_text) linkedin = parsed;
  } else if (parsed.strongest_insight) {
    analysis = parsed;
  }
}

return [{
  json: {
    ...baseData,
    generated_content: {
      tweets: tweets,
      threads: threads,
      linkedin: linkedin,
      analysis: analysis
    }
  }
}];

